// Basic structure ref: https://itp-xstory.github.io/p5js-shaders/#/./docs/setting-up-shaders-in-p5
// The artwork includes a modified version of the image "Prunus mume" by Kakidai, which is licensed under the Creative Commons Attribution-Share Alike 3.0 Unported license. Link to original file: https://commons.wikimedia.org/wiki/File:Prunus_mume.JPG

let nativeShader;
let filterShader;

let nativeLayer;
let bufferLayer;
let filterLayer;

let Taiwan;
let Flower;

function preload(){
  Taiwan = loadImage("https://openprocessing.org/sketch/2323146/files/Taiwan.png");
	Flower = loadImage("https://openprocessing.org/sketch/2323146/files/Prunus_mume.JPG");

  nativeShader = createShader(vert, frag);
  filterShader = createShader(vert, filterfrag);
}

function setup() {
  createCanvas(Taiwan.width, Taiwan.height);
  pixelDensity(1);

  nativeLayer = createGraphics(width, height, WEBGL);
  bufferLayer = createGraphics(width, height);
  filterLayer = createGraphics(width, height, WEBGL);

  noStroke();
  nativeLayer.noStroke();
  bufferLayer.noStroke();
  filterLayer.noStroke();
  bufferLayer.image(Flower, 0, 0, width, height);
}

function draw() {

// [SENTINEL 專家 2 修復] 音訊座標數值防禦
if(typeof window.simulatedMouseX === 'number' && isNaN(window.simulatedMouseX)) window.simulatedMouseX = width*0.5;
if(typeof window.simulatedMouseY === 'number' && isNaN(window.simulatedMouseY)) window.simulatedMouseY = height*0.5;

  setShader(nativeLayer, nativeShader, bufferLayer);
  bufferLayer.image(nativeLayer, 0, 0);
  setShader(filterLayer, filterShader, bufferLayer);
  image(filterLayer, 0, 0);
}

function setShader(canvas, shader, buffer) {
  canvas.shader(shader);
  shader.setUniform('iResolution', [width, height]);
  shader.setUniform('iCanvas', buffer);
  shader.setUniform('iMouse', [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
  shader.setUniform('iTime', frameCount);
  shader.setUniform('iTaiwan', Taiwan);
  canvas.rect(0, 0, width, height);
}

let STOP = false;
function keyPressed() {
  if (key == ' ') {
    STOP = !STOP;
    if (STOP) { noLoop(); }
    else { loop(); }
  }
}

