const snoise3DImage = `
  // MIT License
  // Copyright © 2023 Zaron
  // Permission is hereby granted, free of charge, to any person obtaining a copy of this software and associated documentation files (the "Software"), to deal in the Software without restriction, including without limitation the rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies of the Software, and to permit persons to whom the Software is furnished to do so, subject to the following conditions:
  // The above copyright notice and this permission notice shall be included in all copies or substantial portions of the Software.
  // THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.

  vec4 snoise3DImage(vec2 uv, float scal, float gain, float ofst, vec3 move) {
    uv *= scal;
    float R = snoise(vec3(uv, 100.)+move);
    float G = snoise(vec3(uv, 300.)+move);
    float B = snoise(vec3(uv, 500.)+move);
    vec3 color = ofst+gain*vec3(R, G, B);
    return vec4(color, 1.);
  }

  vec4 snoise3DImage(vec2 uv, float scal, float gain, float ofst, float expo, vec3 move) {
    uv *= scal;
    float R = snoise(vec3(uv, 100.)+move);
    float G = snoise(vec3(uv, 300.)+move);
    float B = snoise(vec3(uv, 500.)+move);
    vec3 col;
    col.r = pow(abs(R), expo)*(step(0., R)*2.-1.);
    col.g = pow(abs(G), expo)*(step(0., G)*2.-1.);
    col.b = pow(abs(B), expo)*(step(0., B)*2.-1.);
    return vec4(ofst+gain*col, 1.);
  }
`


// === Tab: frag ===
// noprotect

const frag = `
  #ifdef GL_ES
  precision mediump float;
  #endif

  uniform vec2 iResolution;
  uniform sampler2D iCanvas;
  uniform vec2 iMouse;
  uniform float iTime;

  ${ snoise3D }
  ${ snoise3DImage }
  ${ displace }

  float random(vec2 uv) {
    return fract(sin(dot(uv, vec2(500.1234, -500.5678)))*9999.);
  }

  float circle(vec2 uv, vec2 pos, float r, float blur) {
    return smoothstep(r+blur, r-blur, length(uv-pos));
  }

  vec4 noise(vec2 uv, float scal, float gain, float ofst, float expo, vec3 move) {
    vec4 noise;
    noise  =     1.0*snoise3DImage((uv-vec2(421., 132))*1., scal, gain, ofst, move);
    noise +=     0.5*snoise3DImage((uv-vec2(913., 687))*2., scal, gain, ofst, move);
    noise +=    0.25*snoise3DImage((uv-vec2(834., 724))*4., scal, gain, ofst, move);
    noise +=   0.125*snoise3DImage((uv-vec2(125., 209))*8., scal, gain, ofst, move);
    noise +=  0.0625*snoise3DImage((uv-vec2(387., 99))*16., scal, gain, ofst, move);
    noise /= 1.9375;
    return noise;
  }

  varying vec2 vTexCoord;
  void main() {
    vec2 uv = vTexCoord;
    vec2 mouse = iMouse.xy/iResolution.xy;
    uv.y = 1.-uv.y;

    float scal = 40.;
    float gain = 1.;
    float ofst = .5;
    float expo = 1.;
    vec3  move = vec3(0., 0., iTime*0.0025);
    vec4 dimg = noise(uv, scal, gain, ofst, expo, move);
    dimg *= (dimg+random(uv));

    float wei = 0.005;
    vec2 duv = displace(uv, dimg.rg, ofst, wei);

    vec4 color = vec4(texture2D(iCanvas, duv).rgb, 1.);

    float cursor = circle(uv, mouse, 0.001, 0.035);
    color = mix(
      color,
      vec4(0., 0., 0., 1.),
      cursor
    );

    gl_FragColor = color;
  }
`


// === Tab: vert ===
// Basic structure ref: https://itp-xstory.github.io/p5js-shaders/#/./docs/how-to-write-a-shader

const vert = `
  #ifdef GL_ES
  precision mediump float;
  #endif

  attribute vec3 aPosition;
  attribute vec2 aTexCoord;

  varying vec2 vTexCoord;

  void main() {
    vTexCoord = aTexCoord;
    vec4 positionVec4 = vec4(aPosition, 1.0);
    positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
    gl_Position = positionVec4;
  }
`


// === Tab: filterfrag ===
// noprotect

const filterfrag = `
  #ifdef GL_ES
  precision mediump float;
  #endif

  uniform vec2 iResolution;
  uniform sampler2D iCanvas;
  uniform vec2 iMouse;
  uniform float iTime;
  uniform sampler2D iTaiwan;

  vec4 invert(vec4 color) {
    vec3 ivrt = vec3(1.-color);
    return vec4(ivrt, 1.);
  }

  vec4 colorAdjust(vec4 color, float brightness, float contrast, float saturation) {
    vec3 RGB = color.rgb;
    RGB *= brightness;
    RGB = (RGB-0.5)*contrast+.5;
    vec3 gray = vec3(dot(RGB, vec3(.2126, .7152, .0722)));
    RGB = mix(gray, RGB, saturation);
    return vec4(RGB, color.a);
  }

  varying vec2 vTexCoord;
  void main() {
    vec2 uv = vTexCoord;
    vec2 mouse = iMouse.xy/iResolution.xy;
    uv.y = 1.-uv.y;

    vec4 color = texture2D(iCanvas, uv);
    vec4 taiwan = texture2D(iTaiwan, uv);
    vec4 ivrtColor = invert(color);

    color = mix(
      ivrtColor+vec4(.25, .3, .3, 1.),
      color+vec4(.2, .1, .5, 1.), 
      taiwan.r
    );

    color = colorAdjust(color, 0.8, 1.5, 1.5);

    gl_FragColor = color;
  }
`

